select count(*)=7 as profile_columns_ready from information_schema.columns where table_schema='mirpanel_community' and table_name='community_profiles' and column_name in ('first_name','last_name','phone','whatsapp','social_links','avatar_path','cover_path');
select coalesce((select profile_count=(select count(*) from mirpanel_community.community_profiles) and profile_hash=(select md5(coalesce(string_agg(jsonb_build_array(user_id,display_name,avatar,blocked,muted_until,muted_permanent,ban_until)::text,'' order by user_id),'')) from mirpanel_community.community_profiles) from mirpanel_community.profile_release_manifest where id=true),false) as original_profiles_preserved;
select relrowsecurity as media_rls from pg_class where oid='mirpanel_community.profile_media'::regclass;
select not has_table_privilege('anon','mirpanel_community.profile_media','select') and not has_table_privilege('authenticated','mirpanel_community.profile_media','select') as no_public_media_access;
